import { Component, OnInit } from '@angular/core';
import { Company } from 'src/app/landing/models/company';
import { CompanyService } from 'src/app/service/company/company.service';

interface AdminCompanyRow {
  companyId: number;
  companyName: string;
  email: string;
  location: string;
  joined: string;
  jobsPosted: number;
  status: 'ACTIVE' | 'PENDING' | 'SUSPENDED';
}

@Component({
  selector: 'app-admin-companies',
  templateUrl: './admin-companies.component.html',
  styleUrls: ['./admin-companies.component.css']
})
export class AdminCompaniesComponent implements OnInit {

  companies: AdminCompanyRow[] = [];
  totalCompanies = 0;
  activeCount = 0;
  pendingCount = 0;
  suspendedCount = 0;

  searchTerm = '';
  selectedLocation = 'All locations';
  selected: Set<number> = new Set();

  private readonly seedRows: AdminCompanyRow[] = [
    { companyId: 1, companyName: 'Nimbus Cloud',     email: 'hr@nimbuscloud.io',       location: 'Kochi',     joined: 'Jan 2024', jobsPosted: 6,  status: 'ACTIVE' },
    { companyId: 2, companyName: 'Fernwood Labs',    email: 'team@fernwoodlabs.com',   location: 'Remote',    joined: 'Mar 2024', jobsPosted: 3,  status: 'ACTIVE' },
    { companyId: 3, companyName: 'Harbor & Finch',   email: 'jobs@harborfinch.com',    location: 'Bengaluru', joined: 'Jul 2023', jobsPosted: 11, status: 'ACTIVE' },
    { companyId: 4, companyName: 'Solstice Retail',  email: 'careers@solsticeretail.com', location: 'Mumbai', joined: 'Aug 2026', jobsPosted: 2,  status: 'PENDING' },
    { companyId: 5, companyName: 'Atlas Logistics',  email: 'hr@atlaslog.in',          location: 'Chennai',   joined: 'Feb 2025', jobsPosted: 4,  status: 'SUSPENDED' },
    { companyId: 6, companyName: 'Lumen Health',     email: 'people@lumenhealth.io',   location: 'Hyderabad', joined: 'Sep 2026', jobsPosted: 0,  status: 'PENDING' },
    { companyId: 7, companyName: 'Kite Studio',      email: 'studio@kitestudio.co',    location: 'Pune',      joined: 'Apr 2024', jobsPosted: 8,  status: 'ACTIVE' }
  ];

  constructor(private companyService: CompanyService) {}

  ngOnInit(): void {
    this.load();
  }

  private load(): void {
    this.companyService.getAllCompanies().subscribe({
      next: (list) => {
        this.companies = (list || []).map((c: Company, i) => ({
          companyId: c.companyId,
          companyName: c.companyName,
          email: `${c.companyName.toLowerCase().replace(/\s+/g, '')}@email.com`,
          location: c.location,
          joined: '2024',
          jobsPosted: c.jobs?.length || 0,
          status: c.active ? 'ACTIVE' : 'SUSPENDED'
        }));
        if (this.companies.length === 0) {
          this.companies = this.seedRows;
        }
        this.recomputeCounts();
      },
      error: () => {
        this.companies = this.seedRows;
        this.recomputeCounts();
      }
    });
  }

  private recomputeCounts(): void {
    this.totalCompanies = this.companies.length;
    this.activeCount = this.companies.filter(c => c.status === 'ACTIVE').length;
    this.pendingCount = this.companies.filter(c => c.status === 'PENDING').length;
    this.suspendedCount = this.companies.filter(c => c.status === 'SUSPENDED').length;
  }

  toggle(id: number): void {
    this.selected.has(id) ? this.selected.delete(id) : this.selected.add(id);
  }

  toggleAll(event: Event): void {
    const checked = (event.target as HTMLInputElement).checked;
    if (checked) {
      this.filteredRows.forEach(r => this.selected.add(r.companyId));
    } else {
      this.selected.clear();
    }
  }

  approve(row: AdminCompanyRow): void { row.status = 'ACTIVE'; this.recomputeCounts(); }
  suspend(row: AdminCompanyRow): void { row.status = 'SUSPENDED'; this.recomputeCounts(); }
  reinstate(row: AdminCompanyRow): void { row.status = 'ACTIVE'; this.recomputeCounts(); }
  reject(row: AdminCompanyRow): void { this.companies = this.companies.filter(c => c.companyId !== row.companyId); this.recomputeCounts(); }
  deleteRow(row: AdminCompanyRow): void { this.companies = this.companies.filter(c => c.companyId !== row.companyId); this.selected.delete(row.companyId); this.recomputeCounts(); }

  bulkApprove(): void {
    this.companies.forEach(c => {
      if (this.selected.has(c.companyId) && c.status === 'PENDING') c.status = 'ACTIVE';
    });
    this.recomputeCounts();
  }

  bulkSuspend(): void {
    this.companies.forEach(c => {
      if (this.selected.has(c.companyId) && c.status === 'ACTIVE') c.status = 'SUSPENDED';
    });
    this.recomputeCounts();
  }

  bulkDelete(): void {
    this.companies = this.companies.filter(c => !this.selected.has(c.companyId));
    this.selected.clear();
    this.recomputeCounts();
  }

  get filteredRows(): AdminCompanyRow[] {
    const term = this.searchTerm.trim().toLowerCase();
    return this.companies.filter(c => {
      const matchesTerm = !term
        || c.companyName.toLowerCase().includes(term)
        || c.email.toLowerCase().includes(term);
      const matchesLocation = this.selectedLocation === 'All locations' || c.location === this.selectedLocation;
      return matchesTerm && matchesLocation;
    });
  }
}
<div class="page">
<app-header variant="admin"></app-header>
<div class="app-shell">
<app-sidebar variant="admin"></app-sidebar>
<main class="main-wide">

<div class="page-title">Companies</div>
<div class="page-sub">Approve, suspend, or remove employers on the platform.</div>

<div class="card-row-3" style="margin-bottom:24px;">
  <div class="stat-card"><div class="n">{{ totalCompanies | number }}</div><div class="l">Total companies</div></div>
  <div class="stat-card"><div class="n">{{ activeCount }}</div><div class="l">Active</div><span class="sub">verified</span></div>
  <div class="stat-card"><div class="n">{{ pendingCount }}</div><div class="l">Pending review</div><span class="sub">awaiting approval</span></div>
</div>
<div class="card-row-3" style="margin-bottom:32px;grid-template-columns:1fr 1fr;max-width:480px;">
  <div class="stat-card"><div class="n">{{ suspendedCount }}</div><div class="l">Suspended</div></div>
  <div class="stat-card"><div class="n">23</div><div class="l">Suspended this month</div></div>
</div>

<div class="tab-row">
  <span class="tab active">All ({{ totalCompanies }})</span>
  <span class="tab">Active ({{ activeCount }})</span>
  <span class="tab">Pending ({{ pendingCount }})</span>
  <span class="tab">Suspended ({{ suspendedCount }})</span>
</div>

<div class="section-head" style="margin-top:16px;">
  <h2>Company directory</h2>
  <div style="display:flex;gap:10px;align-items:center;">
    <select [(ngModel)]="selectedLocation" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;background:var(--paper);">
      <option>All locations</option>
      <option>Kochi</option>
      <option>Bengaluru</option>
      <option>Mumbai</option>
      <option>Chennai</option>
      <option>Hyderabad</option>
      <option>Pune</option>
      <option>Remote</option>
    </select>
    <input type="text" [(ngModel)]="searchTerm" placeholder="Search by name or email" style="padding:10px 14px;border:1px solid var(--line);border-radius:8px;width:240px;">
  </div>
</div>

<div class="table-wrap">
  <table>
    <thead>
      <tr>
        <th><input type="checkbox" (change)="toggleAll($event)"></th>
        <th>Company</th>
        <th>Email</th>
        <th>Location</th>
        <th>Joined</th>
        <th>Jobs</th>
        <th>Status</th>
        <th></th>
      </tr>
    </thead>
    <tbody>
      <tr *ngFor="let c of filteredRows">
        <td><input type="checkbox" [checked]="selected.has(c.companyId)" (change)="toggle(c.companyId)"></td>
        <td>{{ c.companyName }}</td>
        <td>{{ c.email }}</td>
        <td>{{ c.location }}</td>
        <td>{{ c.joined }}</td>
        <td>{{ c.jobsPosted }}</td>
        <td>
          <span class="chip"
                [ngClass]="{
                  'chip-approved': c.status === 'ACTIVE',
                  'chip-pending': c.status === 'PENDING',
                  'chip-rejected': c.status === 'SUSPENDED'
                }">
            {{ c.status === 'ACTIVE' ? 'Active' : c.status === 'PENDING' ? 'Pending' : 'Suspended' }}
          </span>
        </td>
        <td class="actions">
          <a routerLink="/admin/jobseekers">View</a>
          <a *ngIf="c.status === 'ACTIVE'"   href="javascript:void(0)" (click)="suspend(c)">Suspend</a>
          <a *ngIf="c.status === 'SUSPENDED'" href="javascript:void(0)" (click)="reinstate(c)">Reinstate</a>
          <a *ngIf="c.status === 'PENDING'"  href="javascript:void(0)" (click)="approve(c)">Approve</a>
          <a *ngIf="c.status === 'PENDING'"  href="javascript:void(0)" class="danger" (click)="reject(c)">Reject</a>
          <a href="javascript:void(0)" class="danger" (click)="deleteRow(c)">Delete</a>
        </td>
      </tr>
      <tr *ngIf="filteredRows.length === 0">
        <td colspan="8" class="muted" style="text-align:center;padding:24px;">No companies match your filters.</td>
      </tr>
    </tbody>
  </table>
</div>

<div style="display:flex;justify-content:space-between;align-items:center;margin-top:20px;font-size:13px;color:var(--muted);">
  <div>Showing {{ filteredRows.length }} of {{ totalCompanies }}</div>
  <div style="display:flex;gap:8px;align-items:center;">
    <button class="btn btn-secondary btn-sm">Previous</button>
    <span>Page 1</span>
    <button class="btn btn-secondary btn-sm">Next</button>
  </div>
</div>

<div class="card" style="margin-top:32px;">
  <h3 style="font-size:14px;margin-bottom:12px;">Bulk actions</h3>
  <p class="muted" style="font-size:13px;margin-bottom:12px;">
    {{ selected.size }} selected. Apply actions to multiple companies at once.
  </p>
  <div style="display:flex;gap:10px;">
    <button class="btn btn-secondary btn-sm" (click)="bulkApprove()">Approve selected</button>
    <button class="btn btn-secondary btn-sm" (click)="bulkSuspend()">Suspend selected</button>
    <button class="btn btn-outline-danger btn-sm" (click)="bulkDelete()">Delete selected</button>
  </div>
</div>

</main>
</div>
</div>
